import{_ as e,o,c as a,a2 as n}from"./chunks/framework.CQIwe17B.js";const h=JSON.parse('{"title":"Technology Choice Comparisons & Trade-Off Analysis","description":"","frontmatter":{},"headers":[],"relativePath":"04-tech-comparisons.md","filePath":"04-tech-comparisons.md"}'),r={name:"04-tech-comparisons.md"};function s(d,t,i,l,c,m){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="technology-choice-comparisons-trade-off-analysis" tabindex="-1">Technology Choice Comparisons &amp; Trade-Off Analysis <a class="header-anchor" href="#technology-choice-comparisons-trade-off-analysis" aria-label="Permalink to &quot;Technology Choice Comparisons &amp; Trade-Off Analysis&quot;">​</a></h1><h2 id="_1-css-architecture-7-1-sass-vs-alternatives" tabindex="-1">1. CSS Architecture: 7-1 SASS vs Alternatives <a class="header-anchor" href="#_1-css-architecture-7-1-sass-vs-alternatives" aria-label="Permalink to &quot;1. CSS Architecture: 7-1 SASS vs Alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comparison Metric</th><th>Chosen: 7-1 SASS Pattern</th><th>CSS Modules</th><th>Tailwind CSS</th><th>Styled Components (CSS-in-JS)</th><th>Vanilla CSS</th></tr></thead><tbody><tr><td><strong>File Organization</strong></td><td>7 dedicated folders (abstracts, base, components, layout, pages, themes, vendors)</td><td>1 file per component (<code>Button.module.css</code>)</td><td>Utility classes in markup (<code>p-4 text-center</code>)</td><td>Scoped template literals inside JS files</td><td>Single monolithic or split files</td></tr><tr><td><strong>Runtime Overhead</strong></td><td><strong>0 ms (Zero runtime)</strong></td><td>0 ms (Zero runtime)</td><td>0 ms (Zero runtime)</td><td>High (JS parsing, CSS injection, memory footprint)</td><td><strong>0 ms</strong></td></tr><tr><td><strong>BEM Compliance</strong></td><td>Native &amp; seamless (<code>&amp;__element--modifier</code>)</td><td>Scoped classes; BEM redundant</td><td>Anti-BEM; atomic utilities</td><td>Component-centric; BEM redundant</td><td>Manual string maintenance</td></tr><tr><td><strong>Global Design Tokens</strong></td><td>First-class SCSS variables &amp; maps</td><td>Requires CSS variables (<code>var(--color)</code>)</td><td>Config file (<code>tailwind.config.js</code>)</td><td>JS ThemeProvider context</td><td>CSS custom properties</td></tr><tr><td><strong>Fit with Wanderly</strong></td><td><strong>Optimal</strong> (Demonstrates master-level CSS engineering)</td><td>Overkill (No JS framework)</td><td>Avoided (Encapsulates CSS fundamentals)</td><td>Inapplicable (No React/Vue runtime)</td><td>Lacks nesting &amp; mixin modularity</td></tr></tbody></table><ul><li><strong>Why I Used 7-1 SASS</strong>: The 7-1 pattern enforces strict separation of concerns between global configurations (<code>abstracts/</code>), base resets (<code>base/</code>), and reusable UI building blocks (<code>components/</code>), while SCSS nesting enables clean BEM notation without repetitive class typing.</li><li><strong>Why I Did NOT Use Alternatives</strong>: <ul><li><em>Tailwind CSS</em>: Bypasses core CSS cascade and specificity fundamentals that an advanced CSS showcase is intended to prove.</li><li><em>Styled Components</em>: Requires a heavyweight JavaScript runtime (React) to output basic styles, adding unnecessary bundle weight.</li><li><em>Vanilla CSS</em>: Lacks mathematical mixins, functions, and automated vendor prefixing pipelines.</li></ul></li><li><strong>30-Second Interview Answer</strong>: &quot;I chose the 7-1 SASS architecture because it provides an enterprise-grade file structure that cleanly decouples global design tokens and responsive mixins from modular BEM components, generating a lean, zero-runtime production stylesheet.&quot;</li></ul><hr><h2 id="_2-layout-engine-float-grid-vs-flexbox-vs-css-grid" tabindex="-1">2. Layout Engine: Float Grid vs Flexbox vs CSS Grid <a class="header-anchor" href="#_2-layout-engine-float-grid-vs-flexbox-vs-css-grid" aria-label="Permalink to &quot;2. Layout Engine: Float Grid vs Flexbox vs CSS Grid&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Comparison Metric</th><th>Chosen: Float Grid with <code>calc()</code></th><th>CSS Flexbox (<code>display: flex</code>)</th><th>CSS Grid (<code>display: grid</code>)</th></tr></thead><tbody><tr><td><strong>Dimensional Model</strong></td><td>1-Dimensional horizontal columns with clearing</td><td>1-Dimensional flex container (row or column)</td><td>2-Dimensional grid (rows and columns simultaneously)</td></tr><tr><td><strong>Browser Compatibility</strong></td><td><strong>100% (Backwards compatible to IE8)</strong></td><td>High (IE11 partial)</td><td>Modern browsers (IE lacks modern syntax)</td></tr><tr><td><strong>Gutter Management</strong></td><td>Manual <code>margin-right</code> subtraction via <code>calc()</code></td><td><code>gap</code> property (modern) or margin hacks</td><td>Native <code>grid-gap</code> / <code>gap</code></td></tr><tr><td><strong>Clearance Requirements</strong></td><td>Mandatory Micro-Clearfix (<code>::after</code> pseudo)</td><td>Self-clearing</td><td>Self-clearing</td></tr><tr><td><strong>Pedagogical Rigor</strong></td><td><strong>Maximum</strong> (Demonstrates deep layout mechanics)</td><td>Moderate</td><td>Moderate</td></tr></tbody></table><ul><li><strong>Why Float Grid Was Used</strong>: To demonstrate deep understanding of the CSS box model, browser flow, micro-clearfixes, and mathematical <code>calc()</code> dynamic sizing formulas.</li><li><strong>When I Would Switch</strong>: For modern commercial production applications, I would migrate to CSS Grid for page layouts and Flexbox for component-level alignment due to native <code>gap</code> support and elimination of clearfix hacks.</li></ul>',8)])])}const p=e(r,[["render",s]]);export{h as __pageData,p as default};
